<script setup lang="ts">
import { eventFormPayload, isoUtcToDatetimeLocal, validateEventForm, type EventFormErrors, type EventFormState } from '~/composables/event-validation'
import { useToast } from '~/composables/use-toast'
import { PublicApiError } from '~/services/api'
import { useAdminEventsService } from '~/services/admin-events'
import type { AdminEvent, EventStatus } from '~/types/api'

definePageMeta({ layout: 'admin', middleware: 'admin-auth' })
useSeoMeta({ title: 'Eventos · Administración', robots: 'noindex, nofollow' })

const service = useAdminEventsService(); const toast = useToast(); const pageSize = 10
const loading = ref(true); const refreshing = ref(false); const loadError = ref(''); const items = ref<AdminEvent[]>([]); const page = ref(1); const total = ref(0)
const search = ref(''); const selectedStatus = ref<EventStatus | undefined>(); const editingId = ref<number | null>(null); const submitting = ref(false); const deletingId = ref<number | null>(null); const archivingId = ref<number | null>(null)
const errors = ref<EventFormErrors>({}); const titleInput = ref<HTMLInputElement | null>(null); const form = reactive<EventFormState>({ imageId: '', name: '', description: '', startsAt: '', location: '', maximumCapacity: '1', additionalInformation: '', status: 'BORRADOR' })
const confirmModal = reactive({ open: false, title: '', message: '', confirmLabel: 'Confirmar', variant: 'primary' as 'primary' | 'danger' | 'warning', loading: false, action: (async () => {}) as () => Promise<void> })
const totalPages = computed(() => Math.max(1, Math.ceil(total.value / pageSize))); const isEditing = computed(() => editingId.value !== null)
const statuses: Array<{ value: EventStatus; label: string }> = [{ value: 'BORRADOR', label: 'Borrador' }, { value: 'PUBLICADO', label: 'Publicado' }, { value: 'FINALIZADO', label: 'Finalizado' }, { value: 'CANCELADO', label: 'Cancelado' }, { value: 'ARCHIVADO', label: 'Archivado' }]
const statusLabel = (status: EventStatus) => statuses.find(item => item.value === status)?.label ?? status
const formatDate = (value: string) => new Intl.DateTimeFormat('es-GT', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value))
const errorMessage = (error: unknown, fallback: string) => error instanceof PublicApiError ? error.message : fallback
const loadData = async (initial = false) => { if (initial) loading.value = true; else refreshing.value = true; loadError.value = ''; try { const result = await service.list({ q: search.value.trim() || undefined, status: selectedStatus.value, page: page.value, pageSize }); items.value = result.items; total.value = result.pagination.total } catch (error) { const message = errorMessage(error, 'No se pudieron cargar los eventos.'); if (initial) loadError.value = message; else toast.error(message) } finally { loading.value = false; refreshing.value = false } }
const resetForm = () => { editingId.value = null; Object.assign(form, { imageId: '', name: '', description: '', startsAt: '', location: '', maximumCapacity: '1', additionalInformation: '', status: 'BORRADOR' }); errors.value = {} }
const openCreate = () => { resetForm(); nextTick(() => titleInput.value?.focus()) }
const editEvent = (event: AdminEvent) => { editingId.value = event.id; Object.assign(form, { imageId: event.imageId ? String(event.imageId) : '', name: event.name, description: event.description, startsAt: isoUtcToDatetimeLocal(event.startsAt), location: event.location, maximumCapacity: String(event.maximumCapacity), additionalInformation: event.additionalInformation ?? '', status: event.status }); errors.value = {}; nextTick(() => titleInput.value?.focus()) }
const openConfirmation = (title: string, message: string, action: () => Promise<void>, variant: 'primary' | 'danger' | 'warning', confirmLabel: string) => Object.assign(confirmModal, { open: true, title, message, action, variant, confirmLabel, loading: false })
const handleConfirmation = async () => { if (confirmModal.loading) return; confirmModal.loading = true; try { await confirmModal.action(); confirmModal.open = false } catch {} finally { confirmModal.loading = false } }
const requestSave = () => { errors.value = validateEventForm(form); if (Object.keys(errors.value).length) { titleInput.value?.focus(); toast.error('Revisa los campos marcados antes de continuar.'); return }; openConfirmation(isEditing.value ? '¿Actualizar evento?' : '¿Crear evento?', `Confirma que deseas ${isEditing.value ? 'actualizar' : 'crear'} “${form.name.trim()}”.`, executeSave, 'primary', isEditing.value ? 'Actualizar evento' : 'Crear evento') }
const executeSave = async () => { if (submitting.value) return; submitting.value = true; try { const payload = eventFormPayload(form); if (editingId.value) { await service.update(editingId.value, payload); toast.success('El evento se actualizó correctamente.') } else { await service.create(payload); toast.success('El evento se creó correctamente.') }; resetForm(); await loadData() } catch (error) { toast.error(errorMessage(error, 'No se pudo guardar el evento.')); throw error } finally { submitting.value = false } }
const requestArchive = (event: AdminEvent) => openConfirmation('¿Archivar evento?', `“${event.name}” dejará de aparecer entre los eventos publicados.`, () => executeArchive(event), 'warning', 'Archivar evento')
const executeArchive = async (event: AdminEvent) => { if (archivingId.value || deletingId.value) return; archivingId.value = event.id; try { await service.archive(event.id); toast.success('El evento se archivó correctamente.'); await loadData() } catch (error) { toast.error(errorMessage(error, 'No se pudo archivar el evento.')); throw error } finally { archivingId.value = null } }
const requestDelete = (event: AdminEvent) => openConfirmation('¿Eliminar evento permanentemente?', `Esta acción eliminará “${event.name}”. No se puede eliminar un evento con inscripciones.`, () => executeDelete(event), 'danger', 'Eliminar permanentemente')
const executeDelete = async (event: AdminEvent) => { if (deletingId.value || archivingId.value) return; deletingId.value = event.id; try { await service.remove(event.id); toast.success('El evento se eliminó correctamente.'); if (editingId.value === event.id) resetForm(); await loadData() } catch (error) { const message = error instanceof PublicApiError && error.code === 'EVENT_HAS_REGISTRATIONS' ? 'No se puede eliminar un evento que tiene inscripciones. Archívalo en su lugar.' : errorMessage(error, 'No se pudo eliminar el evento.'); toast.error(message); throw error } finally { deletingId.value = null } }
const applyFilters = async () => { page.value = 1; await loadData() }; const goToPage = async (target: number) => { page.value = target; await loadData() }
watch([search, selectedStatus], () => { void applyFilters() }); onMounted(() => { void loadData(true) })
</script>

<template>
  <div class="event-admin">
    <AdminPageHeader eyebrow="Gestión administrativa" title="Eventos" description="Crea, actualiza y gestiona las actividades publicadas para la comunidad estudiantil." />
    <StatePanel v-if="loading" title="Cargando eventos" message="Estamos consultando el listado administrativo." />
    <StatePanel v-else-if="loadError" role="alert" title="No se pudo cargar el módulo" :message="loadError"><button class="secondary-button" type="button" @click="loadData(true)">Reintentar consulta</button></StatePanel>
    <template v-else>
      <section class="manager-card" :class="{ refreshing }" :aria-busy="refreshing">
        <div class="toolbar"><div class="search-field"><label class="sr-only" for="event-search">Buscar eventos</label><input id="event-search" v-model="search" type="search" placeholder="Buscar por nombre, lugar o descripción" /></div><div class="field"><label class="sr-only" for="event-status">Estado</label><select id="event-status" v-model="selectedStatus"><option :value="undefined">Todos los estados</option><option v-for="status in statuses" :key="status.value" :value="status.value">{{ status.label }}</option></select></div><button class="primary-button" type="button" @click="openCreate">＋ Nuevo evento</button></div>
        <div v-if="!items.length" class="empty-state"><h2>No hay eventos para mostrar</h2><p>Prueba con otros filtros o crea el primer evento.</p></div>
        <div v-else class="table-wrap"><table><caption class="sr-only">Listado administrativo de eventos</caption><thead><tr><th>Evento</th><th>Inicio</th><th>Ubicación</th><th>Capacidad</th><th>Estado</th><th><span class="sr-only">Acciones</span></th></tr></thead><tbody><tr v-for="event in items" :key="event.id"><td data-label="Evento"><strong>{{ event.name }}</strong><small>{{ event.description }}</small></td><td data-label="Inicio">{{ formatDate(event.startsAt) }}</td><td data-label="Ubicación">{{ event.location }}</td><td data-label="Capacidad">{{ event.maximumCapacity }}</td><td data-label="Estado"><span :class="['status', `status--${event.status.toLowerCase()}`]">{{ statusLabel(event.status) }}</span></td><td data-label="Acciones"><div class="actions"><button class="secondary-button" type="button" :disabled="deletingId === event.id || archivingId === event.id" @click="editEvent(event)">Editar</button><button v-if="event.status !== 'ARCHIVADO'" class="secondary-button" type="button" :disabled="deletingId === event.id || archivingId === event.id" @click="requestArchive(event)">Archivar</button><button class="danger-button" type="button" :disabled="deletingId === event.id || archivingId === event.id" @click="requestDelete(event)">Eliminar</button></div></td></tr></tbody></table></div>
        <nav v-if="totalPages > 1" class="pagination" aria-label="Paginación de eventos"><span>Mostrando {{ (page - 1) * pageSize + 1 }} a {{ Math.min(page * pageSize, total) }} de {{ total }} eventos</span><div><button type="button" :disabled="page === 1" @click="goToPage(page - 1)">‹ Anterior</button><span aria-live="polite">Página {{ page }} de {{ totalPages }}</span><button type="button" :disabled="page === totalPages" @click="goToPage(page + 1)">Siguiente ›</button></div></nav>
      </section>
      <section class="manager-card"><header class="section-heading"><div><span class="eyebrow">{{ isEditing ? 'Edición' : 'Nuevo evento' }}</span><h2>{{ isEditing ? 'Editar evento' : 'Crear evento' }}</h2></div><button v-if="isEditing" class="secondary-button" type="button" @click="resetForm">Cancelar edición</button></header><form class="form" novalidate @submit.prevent="requestSave"><div class="form-grid"><div class="field"><label for="event-name">Nombre *</label><input id="event-name" ref="titleInput" v-model="form.name" maxlength="220" type="text" :aria-invalid="Boolean(errors.name)" /><span v-if="errors.name" class="field-error" role="alert">{{ errors.name }}</span></div><div class="field"><label for="event-start">Fecha y hora *</label><input id="event-start" v-model="form.startsAt" type="datetime-local" :aria-invalid="Boolean(errors.startsAt)" /><span v-if="errors.startsAt" class="field-error" role="alert">{{ errors.startsAt }}</span></div><div class="field"><label for="event-location">Ubicación *</label><input id="event-location" v-model="form.location" maxlength="255" type="text" :aria-invalid="Boolean(errors.location)" /><span v-if="errors.location" class="field-error" role="alert">{{ errors.location }}</span></div><div class="field"><label for="event-capacity">Capacidad máxima *</label><input id="event-capacity" v-model="form.maximumCapacity" min="1" type="number" :aria-invalid="Boolean(errors.maximumCapacity)" /><span v-if="errors.maximumCapacity" class="field-error" role="alert">{{ errors.maximumCapacity }}</span></div></div><div class="field"><label for="event-description">Descripción *</label><textarea id="event-description" v-model="form.description" maxlength="10000" rows="5" :aria-invalid="Boolean(errors.description)"></textarea><span v-if="errors.description" class="field-error" role="alert">{{ errors.description }}</span></div><div class="form-grid"><div class="field"><label for="event-status-form">Estado *</label><select id="event-status-form" v-model="form.status"><option v-for="status in statuses" :key="status.value" :value="status.value">{{ status.label }}</option></select></div><p class="hint">Las imágenes existentes se conservan al editar. La asociación de nuevas imágenes requiere un flujo administrativo compatible pendiente.</p></div><div class="field"><label for="event-additional">Información adicional</label><textarea id="event-additional" v-model="form.additionalInformation" maxlength="5000" rows="3"></textarea></div><div class="form-actions"><button class="primary-button" type="submit" :disabled="submitting">{{ submitting ? 'Guardando…' : (isEditing ? 'Actualizar evento' : 'Crear evento') }}</button></div></form></section>
    </template>
    <AppConfirmModal :open="confirmModal.open" :title="confirmModal.title" :message="confirmModal.message" :confirm-label="confirmModal.confirmLabel" :variant="confirmModal.variant" :loading="confirmModal.loading" @cancel="confirmModal.open = false" @confirm="handleConfirmation" />
  </div>
</template>

<style scoped>
.event-admin { display: grid; gap: 1.5rem; }.manager-card { display: grid; gap: 1.5rem; padding: clamp(1rem, 3vw, 1.6rem); background: white; border: 1px solid var(--admin-border); border-radius: var(--radius-md); box-shadow: 0 10px 28px rgb(18 31 17 / 5%); }.refreshing { opacity: .72; }.toolbar, .form-grid { display: grid; grid-template-columns: minmax(15rem, 1fr) 12rem auto; gap: .7rem; align-items: end; }.form-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }.search-field input, .field input, .field select, .field textarea { width: 100%; min-height: 2.7rem; padding: .65rem .75rem; color: var(--color-ink); background: white; border: 1px solid var(--admin-border); border-radius: var(--radius-sm); font: inherit; }.search-field input { background: #f5f7fc; }.field { display: grid; gap: .38rem; }.field label { font-size: .86rem; font-weight: 800; }.field textarea { resize: vertical; }.field-error { color: #a4261b; font-size: .8rem; font-weight: 700; }.hint { color: var(--color-muted); font-size: .78rem; }.table-wrap { overflow-x: auto; border: 1px solid #e7ebf3; border-radius: .45rem; }.table-wrap table { width: 100%; min-width: 900px; border-collapse: collapse; }.table-wrap th { padding: .7rem .8rem; color: #6c7891; background: #f1f4fc; font-size: .72rem; text-align: left; text-transform: uppercase; }.table-wrap td { padding: .8rem; border-top: 1px solid #edf0f6; vertical-align: middle; }.table-wrap td strong, .table-wrap td small { display: block; }.table-wrap td small { max-width: 22rem; margin-top: .2rem; color: var(--color-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.actions { display: flex; flex-wrap: wrap; gap: .35rem; }.primary-button, .secondary-button, .danger-button, .pagination button { min-height: 2.7rem; padding: .6rem .85rem; border: 1px solid transparent; border-radius: var(--radius-sm); font: inherit; font-size: .84rem; font-weight: 800; cursor: pointer; }.primary-button { color: white; background: var(--admin-primary); border-color: var(--admin-primary); }.secondary-button { color: var(--admin-primary-dark); background: white; border-color: var(--admin-border); }.danger-button { color: #a4261b; background: #fff1f0; border-color: #e0aaa4; }.primary-button:disabled, .secondary-button:disabled, .danger-button:disabled, .pagination button:disabled { cursor: not-allowed; opacity: .55; }.status { display: inline-flex; padding: .25rem .5rem; border-radius: 999px; font-size: .7rem; font-weight: 900; }.status--publicado { color: #146c3a; background: #e5f6eb; }.status--borrador { color: #7a5511; background: #fff3cf; }.status--archivado, .status--finalizado, .status--cancelado { color: #5d6570; background: #e9edf0; }.empty-state { padding: 2rem 1rem; text-align: center; border: 1px dashed var(--admin-border); border-radius: var(--radius-md); }.empty-state p { margin-top: .35rem; color: var(--color-muted); }.section-heading { display: flex; align-items: end; justify-content: space-between; gap: 1rem; border-bottom: 1px solid var(--admin-border); padding-bottom: 1rem; }.section-heading h2 { margin-top: .3rem; font-size: clamp(1.4rem, 3vw, 2rem); }.eyebrow { color: var(--admin-primary); font-size: .72rem; font-weight: 900; letter-spacing: .1em; text-transform: uppercase; }.form { display: grid; gap: 1rem; }.form-actions { display: flex; justify-content: flex-end; }.pagination { display: flex; align-items: center; justify-content: space-between; gap: 1rem; color: var(--color-muted); font-size: .8rem; }.pagination > div { display: flex; align-items: center; gap: .5rem; }.pagination button { color: var(--admin-primary-dark); background: white; border-color: var(--admin-border); }.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
@media (max-width: 760px) { .toolbar, .form-grid { grid-template-columns: 1fr; }.toolbar > .primary-button { justify-self: stretch; }.section-heading { align-items: start; flex-direction: column; }.table-wrap { overflow: visible; border: 0; }.table-wrap table, .table-wrap tbody, .table-wrap tr, .table-wrap td { display: block; width: 100%; min-width: 0; }.table-wrap table { min-width: 0; }.table-wrap thead { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }.table-wrap tr { padding: .85rem 0; border-top: 1px solid #edf0f6; }.table-wrap td { display: grid; grid-template-columns: 6rem minmax(0, 1fr); gap: .6rem; padding: .35rem 0; border: 0; }.table-wrap td::before { content: attr(data-label); color: #6c7891; font-size: .7rem; font-weight: 900; text-transform: uppercase; }.pagination { align-items: stretch; flex-direction: column; }.pagination > div { justify-content: space-between; } }
</style>
